// Manifesto search: works on the home page and on results.html.
// The archive comes from index.js (generated by build_index.py).

function goSearch() {
    var value = document.getElementById("q").value.trim();
    if (value) window.location.href = "results.html?q=" + encodeURIComponent(value);
}

document.getElementById("go").addEventListener("click", goSearch);
document.getElementById("q").addEventListener("keydown", function (e) {
    if (e.key === "Enter") goSearch();
});

function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function norm(s) {
    // lowercase + strip accents so "revolución" matches "revolucion"
    return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

function countOf(haystack, term) {
    var n = 0, i = haystack.indexOf(term);
    while (i !== -1) { n++; i = haystack.indexOf(term, i + term.length); }
    return n;
}

// Preview: your custom description if the page has one, otherwise an automatic snippet.
function previewFor(doc, terms) {
    if (doc.description) return doc.description;
    var text = doc.text || "";
    var low = norm(text), pos = -1;
    for (var i = 0; i < terms.length; i++) {
        var p = low.indexOf(terms[i]);
        if (p !== -1 && (pos === -1 || p < pos)) pos = p;
    }
    if (pos === -1) return text.slice(0, 160) + (text.length > 160 ? "..." : "");
    var start = Math.max(0, pos - 60);
    var end = Math.min(text.length, pos + 120);
    return (start > 0 ? "..." : "") + text.slice(start, end) + (end < text.length ? "..." : "");
}

function search(query) {
    var terms = norm(query).split(/\s+/).filter(Boolean);
    var out = [];
    (window.ARCHIVE || []).forEach(function (doc) {
        var t = norm(doc.title), k = norm(doc.keywords), d = norm(doc.description), b = norm(doc.text);
        var score = 0, matched = 0;
        terms.forEach(function (term) {
            var s = countOf(t, term) * 10 + countOf(k, term) * 6 + countOf(d, term) * 4 + countOf(b, term);
            if (s > 0) matched++;
            score += s;
        });
        if (matched > 0) out.push({ doc: doc, score: score + matched * 20 });
    });
    out.sort(function (a, b) { return b.score - a.score; });
    return { terms: terms, hits: out };
}

function renderResults(query) {
    var box = document.getElementById("results");
    document.getElementById("results-title").textContent = "Results for " + query;
    document.title = "Manifesto: Results for " + query;
    document.getElementById("q").value = query;

    var res = search(query);
    var today = new Date().toLocaleDateString("en-GB");
    var html = "";

    // template admin
    html += '<div style="margin: 0% 10%;">' +
        '<a href="pages/how-to-upload-on-manifesto.html" style="font-size: 20px;">Want to upload something about this argument?</a> <br>' +
        '<span>If you want to upload something about ' + esc(query) + ' just click here!</span> <br>' +
        '<p style="margin: 0; color: rgb(10, 107, 19);">Manifesto ' +
        '<img style="width: 12px; vertical-align: middle; fill: green;" src="verified-svgrepo-com.svg" alt=""> - ' + today + '</p>' +
        '<br></div>';

    if (res.hits.length === 0) {
        html += '<div style="margin: 0% 10%;"><span>No results in the archive for "' + esc(query) + '".</span></div>';
    }

    res.hits.forEach(function (h) {
        var d = h.doc;
        html += '<div style="margin: 0% 10%;">' +
            '<a href="' + esc(d.href) + '" style="font-size: 20px;">' + esc(d.title) + '</a> <br>' +
            '<span>' + esc(previewFor(d, res.terms)) + '</span> <br>' +
            '<p style="margin: 0; color: rgb(10, 107, 19);">' + esc(d.source || "Manifesto") +
            (d.verified ? ' <img style="width: 12px; vertical-align: middle; fill: green;" src="verified-svgrepo-com.svg" alt="">' : '') +
            ' - ' + esc(d.date) + '</p><br></div>';
    });

    box.innerHTML = html;
}

if (document.getElementById("results")) {
    var q = new URLSearchParams(window.location.search).get("q") || "";
    renderResults(q);
}
